-- Pejuang Yen — Ganti konten kelas AI (warisan GrowWithAI) dengan kelas Bahasa Jepang & persiapan kerja ke Jepang.
-- Strategi: ARSIPKAN semua course/bonus lama (status='archived' → hilang dari katalog /api/resources & /api/courses
-- yang memfilter status='published') lalu SEED kelas starter Pejuang Yen. Aman tanpa risiko FK cascade.

-- 1) Arsipkan semua konten lama (semuanya tema AI)
UPDATE courses        SET status = 'archived', updated_at = '2026-06-30T00:00:00.000Z' WHERE status != 'archived';
UPDATE content_items  SET status = 'archived', updated_at = '2026-06-30T00:00:00.000Z' WHERE content_type IN ('course','bonus') AND status != 'archived';
UPDATE bonuses        SET status = 'archived', updated_at = '2026-06-30T00:00:00.000Z' WHERE status != 'archived';

-- 2) Seed kelas Bahasa Jepang / Persiapan Kerja (placeholder thumbnail lokal; materi diisi via /admin)
INSERT OR IGNORE INTO courses (id, slug, title, subtitle, short_description, description, thumbnail_url, level, category, instructor_name, access_type, price, compare_at_price, status, sort_order, published_at, created_at, updated_at) VALUES
 ('py-course-01','bahasa-jepang-dasar','Bahasa Jepang Dasar: Hiragana & Katakana','Mulai dari nol mengenal aksara Jepang','Kenali dan kuasai Hiragana & Katakana sebagai fondasi belajar bahasa Jepang.','Kelas pembuka untuk pemula total. Kamu akan mengenal aksara Hiragana dan Katakana, cara membaca dan menulisnya, serta pelafalan dasar yang benar — fondasi sebelum masuk tata bahasa N5.','/kelas-placeholder.svg','beginner','Bahasa Jepang','Tim Pejuang Yen','free',0,NULL,'published',1,'2026-06-30T00:00:00.000Z','2026-06-30T00:00:00.000Z','2026-06-30T00:00:00.000Z'),
 ('py-course-02','tata-bahasa-kosakata-n5','Tata Bahasa & Kosakata N5','Pondasi grammar dan kosakata level N5','Pelajari pola kalimat dasar dan kosakata penting setara JLPT N5.','Materi tata bahasa (bunpou) dan kosakata (goi) tingkat dasar setara N5: partikel, bentuk kata kerja, dan percakapan sehari-hari untuk bekal komunikasi awal.','/kelas-placeholder.svg','beginner','Bahasa Jepang','Tim Pejuang Yen','membership_only',0,NULL,'published',2,'2026-06-30T00:00:00.000Z','2026-06-30T00:00:00.000Z','2026-06-30T00:00:00.000Z'),
 ('py-course-03','persiapan-jlpt-n5','Persiapan JLPT N5','Latihan soal & strategi ujian JLPT N5','Simulasi dan pembahasan soal untuk lulus JLPT N5.','Persiapan menyeluruh menghadapi JLPT N5: moji-goi, bunpou, dokkai, dan choukai, lengkap dengan simulasi ujian dan pembahasan strategi mengerjakan soal.','/kelas-placeholder.svg','beginner','Persiapan Ujian','Tim Pejuang Yen','membership_only',0,NULL,'published',3,'2026-06-30T00:00:00.000Z','2026-06-30T00:00:00.000Z','2026-06-30T00:00:00.000Z'),
 ('py-course-04','persiapan-jft-basic','Persiapan JFT-Basic','Lolos JFT-Basic untuk syarat kerja ke Jepang','Materi & simulasi JFT-Basic sebagai syarat program SSW.','Persiapan ujian JFT-Basic (Japan Foundation Test for Basic Japanese): script, vocabulary, conversation, dan reading, dengan simulasi sesuai format CBT resmi.','/kelas-placeholder.svg','beginner','Persiapan Ujian','Tim Pejuang Yen','membership_only',0,NULL,'published',4,'2026-06-30T00:00:00.000Z','2026-06-30T00:00:00.000Z','2026-06-30T00:00:00.000Z'),
 ('py-course-05','persiapan-ujian-ssw','Persiapan Ujian SSW','Persiapan ujian keterampilan Specified Skilled Worker','Pendalaman materi & latihan soal ujian keterampilan SSW.','Persiapan ujian SSW (Tokutei Ginou) untuk berbagai bidang: pemahaman sistem ujian, pendalaman materi keterampilan, dan latihan soal sesuai sektor kerja.','/kelas-placeholder.svg','intermediate','Persiapan Ujian','Tim Pejuang Yen','membership_only',0,NULL,'published',5,'2026-06-30T00:00:00.000Z','2026-06-30T00:00:00.000Z','2026-06-30T00:00:00.000Z'),
 ('py-course-06','tokutei-ginou-sistem-kerja','Tokutei Ginou & Sistem Kerja di Jepang','Pahami jalur, kontrak, dan hak pekerja','Mengenal sistem Tokutei Ginou dan alur kerja resmi ke Jepang.','Pahami skema Tokutei Ginou (SSW): jenis visa, alur perekrutan resmi, hak & kewajiban pekerja, kontrak kerja, serta kehidupan sehari-hari di Jepang.','/kelas-placeholder.svg','intermediate','Persiapan Kerja','Tim Pejuang Yen','membership_only',0,NULL,'published',6,'2026-06-30T00:00:00.000Z','2026-06-30T00:00:00.000Z','2026-06-30T00:00:00.000Z'),
 ('py-course-07','budaya-etika-kerja-jepang','Budaya & Etika Kerja Jepang','Adaptasi budaya & etika kerja Jepang','Pelajari budaya, etika, dan tata krama kerja di Jepang.','Pembekalan budaya kerja Jepang: disiplin, hou-ren-sou, sopan santun (manner), komunikasi di tempat kerja, dan adaptasi sosial agar siap bekerja secara profesional.','/kelas-placeholder.svg','beginner','Persiapan Kerja','Tim Pejuang Yen','free',0,NULL,'published',7,'2026-06-30T00:00:00.000Z','2026-06-30T00:00:00.000Z','2026-06-30T00:00:00.000Z'),
 ('py-course-08','pembekalan-wawancara-cv','Pembekalan Wawancara & CV Kerja Jepang','Siap menghadapi interview perusahaan Jepang','Latihan wawancara kerja & penyusunan CV (rirekisho).','Pembekalan karier: menyusun CV/rirekisho, teknik wawancara dengan perusahaan Jepang, simulasi interview, dan komunikasi profesional saat melamar kerja.','/kelas-placeholder.svg','intermediate','Persiapan Kerja','Tim Pejuang Yen','membership_only',0,NULL,'published',8,'2026-06-30T00:00:00.000Z','2026-06-30T00:00:00.000Z','2026-06-30T00:00:00.000Z');

